fn split_str(s: Str, delimiter: Str) -> Vec<Str> {
    let mut result = vec()
    let mut current = ""
    for c in chars(s) {
        if c == delimiter {
            result = push(result, current)
            current = ""
        } else {
            current = concat(current, c)
        }
    }
    push(result, current)
}

